    "translation": "园子里青青的葵菜上，挂满了亮晶晶的露珠，太阳一出来，露珠就晒干啦。温暖的春天把阳光洒满大地，万物都闪闪发光。可是呀，秋天一到，花儿叶子就会变黄、枯萎。江河里的水哗哗向东流进大海，永远不会回头。我们人也一样，小时候不努力，长大了就要伤心后悔啦！",
    "appreciation": "这首诗最厉害的地方是用大自然来讲道理。它先说春天的美好，再说秋天的衰败，就像告诉我们时间一去不回。露珠会干、叶子会黄、河水流走不回头，全都是我们身边能见到的事情，但诗人用这些告诉我们“少壮不努力，老大徒伤悲”的道理，说得特别有说服力，让人一听就记住。",
    "background": "这也是汉朝乐府里的一首歌。当时的人们看到自然界的万物变化，想到人的生命也是有限的，就写了这首歌来劝告年轻人要珍惜时间。古人没有闹钟也没有日程表，但他们特别懂得时间的宝贵。这首歌就是大人唱给小孩子听的“劝学歌”。",
    "author_info": "和《江南》一样，《长歌行》也是汉乐府收集的民歌。“行”是古代歌曲的一种叫法，“长歌”就是比较长的歌。汉乐府就像古代的“音乐档案馆”，保存了很多老百姓自己创作的歌曲，让我们今天还能听到两千年前的声音。",
