    "funTip": "大草原一望无际，风吹草动露出牛羊！",
    "sceneId": "field",
    "sceneName": "草地",
    "bgTheme": "field",
    "theme": "田园",
    "sentences": [
      {
        "text": "敕勒川，",
        "py": "chì lēi chuān",
        "trans": "",
        "words": []
      },
      {
        "text": "阴山下。",
        "py": "yīn shān xià",
        "trans": "",
        "words": []
      },
      {
        "text": "天似穹庐，",
        "py": "tiān shì qióng lú",
        "trans": "",
        "words": []
      },
      {
        "text": "笼盖四野。",
        "py": "lóng gài sì yě",
        "trans": "",
        "words": []
      },
      {
        "text": "天苍苍，",
        "py": "tiān cāng cāng",
        "trans": "",
        "words": []
      },
      {
        "text": "野茫茫，",
        "py": "yě máng máng",
        "trans": "",
        "words": []
      },
      {
        "text": "风吹草低见牛羊。",
        "py": "fēng chuī cǎo dī jiàn niú yáng",
        "trans": "一阵风吹过，草低下去露出了牛羊。",
        "words": [
          {
            "word": "见",
            "note": "同现，露出"
          }
        ]
      }
    ],
    "translation": "敕勒川这片大草原呀，就在高高的阴山脚下。抬头看，天空像一个巨大的圆顶帐篷，把大地盖得严严实实的。天是那么蓝，草原是那么绿，一眼望不到边。一阵风吹过来，高高的草弯下了腰，藏在草丛里的牛羊就露了出来——哇，这么多牛羊！",
    "appreciation": "这首诗只用了几句话，就画出了一幅巨大的草原画卷。“天似穹庐”这个比喻特别有趣，把天空比作蒙古包，草原上长大的孩子一看就懂。“风吹草低见牛羊”是全诗最美的一句，风吹草动的画面里藏着牛羊，像揭开谜底一样让人惊喜。整首诗读起来豪迈又辽阔，让人好像站在大草原上深呼吸。",
    "background": "这是一千五百多年前北方草原上流传的民歌。敕勒族是当时生活在蒙古大草原上的游牧民族，他们骑马放牧，住在帐篷里。这首歌是他们用自己民族的语言唱的，后来被翻译成汉语，流传了下来。歌词里充满了对家乡草原的热爱。",
    "author_info": "北朝民歌是指南北朝时期（公元420-589年）北方地区流传的民间歌谣。那时北方是游牧民族生活的地方，所以这些歌和南方的《江南》风格完全不同。《敕勒歌》是最有名的一首北朝民歌，豪迈大气，充满了草原的味道。",
