    "translation": "我小时候离开家乡，到老了才回来。虽然说话的家乡口音一点没变，但头发已经花白花白的了。村子里的小孩子们看见我，都不认识我是谁，笑着跑过来问：“老爷爷，您是从哪里来的客人呀？”听到这话，我心里又高兴又有点难过。",
    "appreciation": "这首诗写的是一个老人回到家乡时又开心又心酸的感觉。最动人的是最后两句：家乡的小孩不认识诗人，把他当成了远方来的客人。明明这里是自己的家，却被当成客人——这种感觉用最简单的话说出来，反而让人特别感动。全诗没有一个难字，但大人小孩读了都会在心里想一想。",
    "background": "贺知章年轻时离开家乡去京城做官，一走就是五十多年。等到八十多岁辞官回乡的时候，家乡的很多东西都变了，小时候的玩伴大多不在了，新一辈的孩子根本不认识他。他心里百感交集，就写下了这首诗。",
    "author_info": "贺知章是唐朝活得最久的诗人之一，活到了八十六岁。他当过大官，但为人特别随和。晚年辞官回乡时，唐玄宗还亲自写诗为他送行。《回乡偶书》是他在回乡路上写的，写出了无数游子回家的共同心情。",
    "notes": "偶书：随便写的诗。偶：说明诗写作得很偶然，是随时有所见、有所感就写下来的。少小离家：贺知章三十七岁中进士，在此以前就离开家乡。老大：年纪大了。贺知章回乡时已年逾八十。乡音：家乡的口音。无改：没什么变化。一作“难改”。鬓毛：额角边靠近耳朵的头发。一作“面毛”。衰：减少，疏落。鬓毛衰：指鬓毛减少，疏落。相见：即看见我；相：带有指代性的副词。不相识：即",
    "tags": [
      "唐诗三百首",
      "小学古诗",
      "早教"
    ],
