    "funTip": "远远望去，黄河像飘到了白云之间，边塞的孤城好壮观！",
    "sceneId": "pond",
    "sceneName": "池塘",
    "bgTheme": "",
    "theme": "边塞",
    "sentences": [
      {
        "text": "黄河远上白云间，",
        "py": "huáng hé yuǎn shàng bái yún jiān",
        "trans": "远远望去，黄河好像流到了白云间，",
        "words": [
          {
            "word": "远上",
            "note": "远远地向上游望去"
          }
        ]
      },
      {
        "text": "一片孤城万仞山。",
        "py": "yī piàn gū chéng wàn rèn shān",
        "trans": "一座孤城坐落在万丈高山之间。",
        "words": [
          {
            "word": "仞",
            "note": "古代长度单位，一仞约七八尺"
          },
          {
            "word": "万仞",
            "note": "形容极高"
          }
        ]
      },
      {
        "text": "羌笛何须怨杨柳，",
        "py": "qiāng dí hé xū yuàn yáng liǔ",
        "trans": "羌笛啊何必吹那哀怨的《折杨柳》曲，",
        "words": [
          {
            "word": "羌笛",
            "note": "羌族的笛子"
          },
          {
            "word": "杨柳",
            "note": "指《折杨柳》曲，古代送别曲"
          }
        ]
      },
      {
        "text": "春光不度玉门关。",
        "py": "chūn guāng bù dù yù mén guān",
        "trans": "",
        "words": []
      }
    ],
    "translation": "黄河远远地从天边流过来，奔腾在白云之间。一座孤零零的城池，立在高高的万丈山峰旁边。守城的士兵吹着羌笛，那《折杨柳》的曲子好悲伤呀。春风啊春风，你为什么吹不到这遥远的边疆来呢？这里多么需要春天的温暖啊！",
    "appreciation": "这首诗把边疆的壮阔和寂寞写得特别打动人。前两句写景，一远一近：黄河从白云间奔来，孤城在高山旁伫立，画面特别宏大。后两句写情：春风不肯吹到这里，既说天气寒冷，也说这里缺少温暖和关怀。羌笛的曲子听起来很忧伤，但诗人说“何须怨”，有一种坚强的感觉，让人又感动又敬佩。",
    "background": "王之涣生活在唐朝最强盛的时期，但仍然有边疆战争。凉州是西北边疆的重要城市，驻扎着很多守卫边疆的士兵。他们远离家乡，生活很艰苦。这首诗写出了士兵们思念家乡的心情，也写出了边疆的苍凉和壮美。",
    "author_info": "王之涣（688-742年）是唐朝著名边塞诗人。他一生写的诗不多，只有六首流传下来，但每一首都非常经典。他和王昌龄、高适是好朋友，三人常在一起写诗。《登鹳雀楼》和《凉州词》都是千古传诵的名篇。",
    "notes": "凉州词：又名《出塞》。为当时流行的一首曲子《凉州》配的唱词。郭茂倩《乐府诗集》卷七十九《近代曲词》载有《凉州歌》，并引《乐苑》云：“《凉州》，宫调曲，开元中西凉府都督郭知运进。”凉州，属唐陇右道，治所在姑臧县（今甘肃",
    "tags": [
      "七言绝句",
      "黄河",
      "边疆"
    ],
    "gwd_id": "96da51114a58",
    "gwd_url": "https://www.guwendao.net/shiwenv_96da51114a58.aspx",
    "translation_gwd": "",
    "appreciation_gwd": "其一诗人初到凉州，面对黄河、边城的辽阔景象，又耳听着《折杨柳》曲，有感而发，写成了这首表现戍守边疆的士兵思念家乡情怀的诗作。\n诗的前两句描绘了西北边地广漠壮阔的风光。首句抓住自下（游）向上（游）、由近及远眺望黄河的特殊感受，描绘出“黄河远上白云间”的动人画面：汹涌澎湃波浪滔滔的黄河竟像一条丝带迤逦飞上云端。写得真是神思飞跃，气象开阔。诗人的另一名句“黄河入海流”，其观察角度与此正好相反，是自上而下的目送；而李白的“黄河之水天上来”，虽也写观望上游，但视线运动却又由远及近，与此句不同。“黄河入海流”和“黄河之水天上来”，同是着意渲染黄河一泻千里的气派，表现的",
    "background_gwd": "",
    "author_info_gwd": "王之涣（688年—742年），是盛唐时期的著名诗人，字季凌，汉族，绛州（今山西新绛县）人。豪放不羁，常击剑悲歌，其诗多被当时乐工制曲歌唱。名动一时，他常与高适、王昌龄等相唱和，以善于描写边塞风光著称。其代表作有《登鹳雀楼》、《凉州词》等。“白日依山尽，黄河入海流。欲穷千里目，更上一层楼”，更是千古绝唱。"
