    "funTip": "站得越高，看得越远！",
    "sceneId": "mountain",
    "sceneName": "山林",
    "bgTheme": "mountain",
    "theme": "写景",
    "sentences": [
      {
        "text": "白日依山尽，",
        "py": "bái rì yī shān jǐn",
        "trans": "夕阳贴着远山慢慢落下去了，",
        "words": [
          {
            "word": "依",
            "note": "靠着，贴着"
          },
          {
            "word": "尽",
            "note": "消失"
          }
        ]
      },
      {
        "text": "黄河入海流。",
        "py": "huáng hé rù hǎi liú",
        "trans": "黄河水朝着大海的方向奔流而去。",
        "words": [
          {
            "word": "入",
            "note": "流进"
          }
        ]
      },
      {
        "text": "欲穷千里目，",
        "py": "yù qióng qiān lǐ mù",
        "trans": "想要看到千里之外的景色，",
        "words": [
          {
            "word": "欲",
            "note": "想要"
          },
          {
            "word": "穷",
            "note": "穷尽，看到尽头"
          }
        ]
      },
      {
        "text": "更上一层楼。",
        "py": "gèng shàng yī céng lóu",
        "trans": "就要再登上一层高楼。",
        "words": [
          {
            "word": "更",
            "note": "再"
          }
        ]
      }
    ],
    "translation": "太阳靠着远处的高山慢慢地落下去了，黄河水哗哗地向大海奔腾而去。想要看到更远更美的风景，就要再努力往上爬一层楼！站得越高，看得越远，原来世界这么大、这么美呀！",
    "appreciation": "这首诗从看风景讲到人生道理，过渡得特别自然。前两句写落日和黄河，画面壮阔，让人感受到天地之大。后两句“欲穷千里目，更上一层楼”，既说真的爬楼，也说人要有上进心。这句话太有力量了，千百年来一直鼓励着人们不断努力、不断向上。用最简单的语言说出最深刻的道理，这就是好诗的魅力。",
    "background": "鹳雀楼在今天的山西省，是古代一座非常有名的楼，因为经常有鹳雀鸟在上面停留而得名。王之涣有一天登上这座楼，看到壮丽的黄河和落日，心情激动，就在楼上题了这首诗。后来这座楼虽然毁坏了，但这首诗让它的名字永远流传。",
    "author_info": "王之涣和王昌龄、高适一样，都是盛唐边塞诗的代表人物。他喜欢用最简洁的语言表达最深远的意境。“更上一层楼”成为中国人最熟悉的励志名句之一，一千多年来一直激励着人们不断进步。",
    "notes": "鹳（guàn）雀（què）楼：旧址在山西永济市，前对中条山，下临黄河。传说常有鹳雀在此停留，故有此名。白日：太阳。依：依傍。尽：消失。 这句话是说太阳依傍山峦沉落。欲：想要得到某种东西或达到某种目的的愿望，但也有希望、想要的意思。穷：尽，使达到极点。千里目：眼界宽阔。更：再。",
    "tags": [
      "唐诗三百首",
      "五言绝句",
      "幼儿古诗"
    ],
    "gwd_id": "c90ff9ea5a71",
    "gwd_url": "https://www.guwendao.net/shiwenv_c90ff9ea5a71.aspx",
    "translation_gwd": "",
    "appreciation_gwd": "这首诗写诗人在登高望远中表现出来的不凡的胸襟抱负，反映了盛唐时期人们积极向上的进取精神。\n诗的前两句写所见。“白日依山尽”写远景，写山，写的是登楼望见的景色，“黄河入海流”写近景，写水写得景象壮观，气势磅礴。这里，诗人运用极其朴素、极其浅显的语言，既高度形象又高度概括地把进入广大视野的万里河山，收入短短十个字中；而后人在千载之下读到这十个字时，也如临其地，如见其景，感到胸襟为之一开。\n首句写遥望一轮落日向着楼前一望无际、连绵起伏的群山西沉，在视野的尽头冉冉而没。这是天空景、远方景、西望景。次句写目送流经楼前下方的黄河奔腾咆哮、滚滚南来，又在远处折而东向",
    "background_gwd": "",
    "author_info_gwd": "王之涣（688年—742年），是盛唐时期的著名诗人，字季凌，汉族，绛州（今山西新绛县）人。豪放不羁，常击剑悲歌，其诗多被当时乐工制曲歌唱。名动一时，他常与高适、王昌龄等相唱和，以善于描写边塞风光著称。其代表作有《登鹳雀楼》、《凉州词》等。“白日依山尽，黄河入海流。欲穷千里目，更上一层楼”，更是千古绝唱。"
