    "translation": "我一个人在遥远的外地做客，每到过节的时候，就更加想念家里的亲人了。今天是九九重阳节，我想，远方的兄弟们一定都登上了高高的山，每个人都插上了茱萸草——可是数一数，偏偏少了我一个人，他们肯定也在想念我吧！",
    "appreciation": "这首诗最巧妙的地方是最后一句。“遍插茱萸少一人”，诗人不说自己想念兄弟，反而说兄弟们插茱萸时发现少了他。这样一来，想念就从单向变成了双向——我想你们，你们也在想我。这种写法特别聪明，也让人更加心酸。从“独在异乡”到“每逢佳节倍思亲”，再到最后的“少一人”，层层递进，把思乡之情写得越来越浓。",
    "background": "王维写这首诗时才十七岁，还是个少年呢！他离开家乡山西，到长安去求学考试。在繁华的大城市里，他一个人生活，特别想念家人。九月九日重阳节那天，按照习俗家人都要一起登高插茱萸，王维想到自己不能回家，就写下了这首思念的诗。",
    "author_info": "王维少年成名，诗、画、音乐都很出色。“每逢佳节倍思亲”这句话后来成了中国人表达思乡之情最常用的一句话，一千多年来打动了无数游子的心。",
    "notes": "九月九日：即重阳节。古以九为阳数，故曰重阳。忆：想念。山东：王维迁居于蒲县（今山西永济市），在函谷关与华山以东，所以称山东。异乡：他乡、外乡。为异客：作他乡的客人。佳节：美好的节日。登高：古有重阳节登高的风俗。茱萸（zhūyú）：是指吴茱萸。为芸香科植物吴茱萸的近成熟果实。《本草纲目》吴茱萸【集解】苏颂引周处《风土记》云：“俗尚九月九日谓之上九，",
    "tags": [
      "唐诗三百首",
      "小学古诗",
      "七言绝句"
    ],
    "gwd_id": "d75a706935de",
    "gwd_url": "https://www.guwendao.net/shiwenv_d75a706935de.aspx",
    "translation_gwd": "",
    "appreciation_gwd": "这首王维少年时期创作的抒情小诗，和他后来那些富于画意、构图设色非常讲究的山水诗不同，写得非常朴素。但这首诗却有着强烈的打动人心的力量，尤其是对作客他乡的人们。这种力量，首先来自它的朴质、深厚和高度的概括。\n王维家居蒲州，在华山之东，所以题称“忆山东兄弟”。写这首诗时他大概正在长安谋取功名。繁华的帝都对当时热中仕进的年轻士子虽有很大吸引力，但对一个少年游子来说，毕竟是举目无亲的“异乡”；而且越是繁华热闹，在茫茫人海中的游子就越显得孤孑无亲。\n“独在异乡为异客”，开篇一句写出了诗人在异乡的孤独之感。诗人在这短短的一句话中用了一个“独”、两个“异”字，可见诗",
    "background_gwd": "",
    "author_info_gwd": "王维（701年－761年，一说699年—761年），字摩诘(jié)，号摩诘居士。汉族，河东蒲州（今山西运城）人，祖籍山西祁县，唐朝诗人，有“诗佛”之称。苏轼评价其：“味摩诘之诗，诗中有画；观摩诘之画，画中有诗。”开元九年（721年）中进士，任太乐丞。天宝年间，拜吏部郎中、给事中。唐肃宗乾元年间任尚书右丞，世称“王右丞”。王维是盛唐诗人的代表，今存诗400余首，重要诗作有《相思》《山居秋暝》等。王维精通佛学，受禅宗影响很大。佛教有一部《维摩诘经》，是王维名和字的由来。王维诗书画都很有名，多才多艺，音乐也很精通。与孟浩然合称“王孟”。"
