    "note": "教材仅选前4句'小时不识月,呼作白玉盘'为L1；全篇80字为L3，低幼只呈现节选",
    "paragraphs": [
      "小时不识月，呼作白玉盘。",
      "又疑瑶台镜，飞在白云端。",
      "仙人垂两足，桂树作团团。",
      "白兔捣药成，问言与谁餐。",
      "蟾蜍蚀圆影，大明夜已残。",
      "羿昔落九乌，天人清且安。",
      "阴精此淪惑，去去不足观。",
      "忧来其如何，凄怆摧心肝。"
    ],
