    "sentences": [
      {
        "text": "朝辭白帝彩云间，",
        "py": "cháo cí bái dì cǎi yún jiān",
        "trans": "",
        "words": []
      },
      {
        "text": "千里江陵一日还。",
        "py": "qiān lǐ jiāng líng yī rì hái",
        "trans": "千里外的江陵一天就能回到。",
        "words": [
          {
            "word": "江陵",
            "note": "地名，在今湖北"
          }
        ]
      },
      {
        "text": "两岸猨声啼不尽，",
        "py": "liǎng àn yuán shēng tí bù jìn",
        "trans": "",
        "words": []
      },
      {
        "text": "轻舟已过万重山。",
        "py": "qīng zhōu yǐ guò wàn zhòng shān",
        "trans": "轻快的小船已经穿过了万重高山。",
        "words": [
          {
            "word": "轻舟",
            "note": "轻快的小船"
          }
        ]
      }
    ],
    "translation": "清晨辞别了彩云之间的白帝城，我坐船顺流而下，千里之外的江陵一天就能到达。两边的猿猴叫声还在耳边不停地回荡，轻快的小船已经像飞一样穿过了万重高山！这感觉太痛快啦！",
    "appreciation": "这首诗读起来就像坐过山车一样快！“千里江陵一日还”——千里路一天到，速度多快呀。“轻舟已过万重山”——轻舟在峡谷间穿行，“万重山”刷刷地往后退，画面感超强。整首诗的节奏本身就是飞奔的，每个字都好像踩在船桨的节拍上。李白把重获自由的狂喜心情全写进这艘“飞”起来的小船里了。",
    "background": "李白晚年因为卷入政治风波，被流放到了很远的夜郎（现在的贵州一带）。走到白帝城的时候，突然传来了好消息——皇帝大赦天下，李白自由了！他欣喜若狂，立刻乘船掉头东下。这首诗写的就是他从白帝城顺流而下的路上那种重获自由的畅快心情。",
    "author_info": "李白一生大起大落，得意时被皇帝召进宫中写诗，失意时被流放边疆。但不管遭遇什么，他始终保持着一颗豪迈乐观的心。《早发白帝城》就是他在绝境中重获新生后写下的，全诗充满了对生命的热爱和对自由的向往。",
    "notes": "发：启程。白帝城：故址在今重庆市奉节县白帝山上。杨齐贤注：“白帝城，公孙述所筑。初，公孙述至鱼复，有白龙出井中，自以承汉土运，故称白帝，改鱼复为白帝城。”王琦注：“白帝城，在夔州奉节县，与巫山相近。所谓彩云，正指巫山之云也。”",
    "tags": [
      "唐诗三百首",
      "中国诗词大会2024",
      "中国诗词大会2023"
    ],
    "gwd_id": "0f81015a040c",
    "gwd_url": "https://www.guwendao.net/shiwenv_0f81015a040c.aspx",
    "translation_gwd": "",
    "appreciation_gwd": "唐代安史之乱初期，唐玄宗奔蜀，太子李亨留讨安禄山，不久，李亨既位，史唐肃宗。玄宗又曾命令儿子永王李璘督兵平叛，永王李璘在江陵，召兵万人，自树一帜，肃宗怀疑他争夺帝位，已重兵相压，李璘兵败被杀。李白曾经参加过永王李璘的幕府，被加上“附逆”罪流放夜郎（今贵州遵义），当他行至巫山（今重庆境内）的时候，肃宗宣布大赦，李白也被赦免，他像出笼的鸟一样，立刻从白帝城东下，返回江陵（今湖北荆州）。此诗即回舟抵江陵时所作，所以诗题一作“白帝下江陵”。\n此诗意在描摹自白帝至江陵一段长江，水急流速，舟行若飞的情况。首句写白帝城之高；二句写江陵路遥，舟行迅速；三句以山影猿声烘托行舟飞进；",
    "background_gwd": "",
    "author_info_gwd": "李白（701年~762年），字太白，号青莲居士，出生于蜀郡绵州昌隆县（今四川省绵阳市江油市青莲镇），一说山东人，一说生于西域碎叶，祖籍陇西成纪（今甘肃天水秦安县），凉武昭王李暠九世孙。唐代伟大的浪漫主义诗人，被后人誉为“诗仙”，与杜甫并称为“李杜”，为了与另两位诗人李商隐与杜牧即“小李杜”区别，杜甫与李白又合称“大李杜”。其人爽朗大方，爱饮酒作诗，喜交友。李白深受黄老列庄思想影响，有《李太白集》传世，诗作中多为醉时写就，代表作有《望庐山瀑布》《行路难》《蜀道难》《将进酒》《早发白帝城》等。"
