    "translation": "春天到了，太阳照得大地暖洋洋的，青山绿水格外美丽。春风里飘来花草的清香。泥土融化了，燕子飞来飞去忙着衔泥筑巢；温暖的沙滩上，一对对鸳鸯静静地睡着。",
    "appreciation": "这首诗用二十个字就画出了一幅春天的画！前两句'迟日江山丽，春风花草香'从远处看，天大地大，风光无限；后两句'泥融飞燕子，沙暖睡鸳鸯'凑近了看，燕子忙碌、鸳鸯安睡，一动一静，特别有意思。诗人用眼睛看、用鼻子闻，把春天的温暖、明亮和生机都写出来了。读这首诗，就好像在春天的公园里散步一样舒服。",
    "background": "杜甫在成都草堂居住时，生活比较安宁。经历了多年的战乱奔波，他格外珍惜这份平静。一个春日，他看到草堂周围生机勃勃的景象——燕子飞回来了，鸳鸯在暖沙上睡觉，花草飘香，心里充满了欣慰和喜悦，于是写下了这首小诗。",
    "author_info": "杜甫（712—770），字子美，号少陵野老，唐代最伟大的诗人之一，与李白并称'李杜'。他的诗真实记录了唐代社会的变迁，被称作'诗史'。代表作有《春望》《登高》《兵车行》等。",
    "notes": "李龟年：唐朝开元、天宝年间的著名乐师，擅长唱歌。因为受到皇帝唐玄宗的宠幸而红极一时。“安史之乱”后，李龟年流落江南，卖艺为生。岐王：唐玄宗李隆基的弟弟李隆范（后改名李范），以好学爱才著称，雅善音律。寻常：经常。崔九：崔涤，在兄弟中排行第九，中书令崔湜的弟弟。玄宗时，曾任殿中监，出入禁中，得玄宗宠幸。崔姓，是当时一家大姓，以此表明李龟年原来受赏识。江南：这里指今湖南省一带。",
    "tags": [
      "唐诗三百首",
      "初中古诗",
      "小学生必背古诗80首"
    ],
    "gwd_id": "514b8bc0ee4f",
    "gwd_url": "https://www.guwendao.net/shiwenv_514b8bc0ee4f.aspx",
    "translation_gwd": "",
    "appreciation_gwd": "诗是感伤世态炎凉的。李龟年是唐玄宗初年的著名歌手，常在贵族豪门歌唱。杜甫少年时才华卓著，常出入于岐王李隆范和中书监崔涤的门庭，得以欣赏李龟年的歌唱艺术。诗的开首二句是追忆昔日与李龟年的接触，寄寓诗人对开元初年鼎盛的眷怀；后两句是对国事凋零，艺人颠沛流离的感慨。仅仅四句却概括了整个开元时期（注：开元时期为713年—741年）的时代沧桑，人生巨变。语极平淡，内涵却无限丰满。\n李龟年是开元时期“特承顾遇”的著名歌唱家。杜甫初逢李龟年，正是在意气风发的少年时期，正值“开元盛世”。杜甫因才华早著而受到歧王李范和秘书监崔涤的赏识，得以在他们的府邸欣赏李龟年的歌唱。在杜甫的心目",
    "background_gwd": "",
    "author_info_gwd": "杜甫（712－770），字子美，自号少陵野老，世称“杜工部”、“杜少陵”等，汉族，河南府巩县（今河南省巩义市）人，唐代伟大的现实主义诗人，杜甫被世人尊为“诗圣”，其诗被称为“诗史”。杜甫与李白合称“李杜”，为了跟另外两位诗人李商隐与杜牧即“小李杜”区别开来，杜甫与李白又合称“大李杜”。他忧国忧民，人格高尚，他的约1400余首诗被保留了下来，诗艺精湛，在中国古典诗歌中备受推崇，影响深远。759-766年间曾居成都，后世有杜甫草堂纪念。"
