    "sentences": [
      {
        "text": "独怜幽草涧边生，",
        "py": "dú lián yōu cǎo jiàn biān shēng",
        "charCount": 8,
        "trans": "",
        "words": []
      },
      {
        "text": "上有黄鹂深树鸣。",
        "py": "shàng yǒu huáng lí shēn shù míng",
        "charCount": 8,
        "trans": "",
        "words": []
      },
      {
        "text": "春潮带雨晚来急，",
        "py": "chūn cháo dài yǔ wǎn lái jí",
        "charCount": 8,
        "trans": "",
        "words": []
      },
      {
        "text": "野渡无人舟自横。",
        "py": "yě dù wú rén zhōu zì héng",
        "charCount": 8,
        "trans": "",
        "words": []
      }
    ],
    "translation": "我只喜爱那生长在涧边幽静处的青草，上面还有黄鹂鸟儿在树丛深处婉转地啼叫。春天的潮水伴着傍晚的雨，水势来得又急又猛；而那荒野的渡口，小船没有人管，被水流推着，独自横在岸边。",
    "appreciation": "这是一首安静又有深意的小诗。诗人喜欢的不是热闹的牡丹玫瑰，而是涧边自生自长的幽草，这种不争不抢、安安静静的生命力特别打动人。黄鹂深树鸣叫，声音好听但找不到鸟儿在哪，有一种神秘的美。最后写潮水急涨、渡口无人、小船自横——看起来有点荒凉，可是那只小船随便漂着的样子，又让人觉得自在、从容。全诗没有一句说大道理，却让人感受到一种淡然自得的心境。",
    "background": "韦应物在滁州做官时写了这首诗。滁州西涧是他常去散步的地方，那里远离城市的喧嚣。韦应物是一个喜欢清静的人，他厌倦官场的勾心斗角，向往山水田园的生活。这首诗写的就是他在西涧看到的风景，也是他自己内心世界的写照——希望像那只小船一样，不被管束，自由自在。",
    "author_info": "韦应物（737—792），唐代诗人，以山水田园诗著称。他的诗风格清丽淡雅，意境深远，与王维、孟浩然齐名。代表作有《滁州西涧》《秋夜寄邱员外》等。",
    "notes": "滁州：在今安徽滁州以西。西涧：在滁州城西，俗名称上马河。独怜：唯独喜欢。幽草：幽谷里的小草。幽，一作“芳”。生：一作“行”。深树：枝叶茂密的树。深，《才调集》作“远”。树，《全唐诗》注“有本作‘处’”。春潮：春天的潮汐。野渡：郊野的渡口。自横：指随意漂浮。",
