    "translation": "一个小娃娃撑着一条小船，偷偷地划到池塘里去采白莲。他还不懂得怎么隐蔽行踪，小船走过的地方，浮萍被分开了，留下一道长长的水路，一下子就让人知道他来过这里。",
    "appreciation": "这首诗可爱极了！写的是一个天真烂漫的小孩子，偷偷撑船去采莲花。'偷'字用得特别妙——不是坏，是小朋友那种想做一件小事又不想被大人发现的好玩心态。最好笑的是后面，孩子以为自己藏得很好，可是小船划过的水面，浮萍分开了长长一道痕迹，把行踪暴露得清清楚楚。读到这里，我们都会忍不住笑起来，因为这种'自以为聪明其实露馅'的小事，每个人都经历过。",
    "background": "白居易晚年退居洛阳，生活悠闲，喜欢观察生活中的小事，尤其喜欢小孩子的天真烂漫。《池上》写的就是他看到的池塘边的一个小故事——一个孩子偷偷撑船采莲的可爱场景。诗人用一个长者的慈爱目光，捕捉到了童年的调皮与纯真，写得充满童趣。",
    "author_info": "白居易（772—846），字乐天，晚号香山居士，唐代三大诗人之一。他的诗通俗易懂，老人小孩都能读懂，流传极广。代表作有《池上》《赋得古原草送别》《忆江南》等。",
    "notes": "小娃：指小孩子。艇：船。白莲：白色的莲花。踪迹：指被小艇划开的浮萍。浮萍：水生植物，椭圆形叶子浮在水面，叶下面有须根，夏季开白花。",
    "tags": [
      "早教",
      "小学古诗",
      "小学生必背古诗70首"
    ],
    "gwd_id": "a8f44614071a",
    "gwd_url": "https://www.guwendao.net/shiwenv_a8f44614071a.aspx",
    "translation_gwd": "",
    "appreciation_gwd": "这首诗好比一组镜头，摄下一个小孩儿偷采白莲的情景。从诗的小主人公撑船进入画面，到他离去只留下被划开的一片浮萍，有景有色，有行动描写，有心理刻画，细致逼真，富有情趣；而这个小主人公的天真幼稚、活泼淘气的可爱形象，也就栩栩如生，跃然纸上了。\n这是一首描写儿童生活的诗。诗人以他特有的通俗风格将诗中的小娃娃描写得非常可爱、可亲。整首诗如同大白话，但极富韵味，令人读后忍俊不禁、哑然失笑。 诗人在诗中叙述一个小娃娃生活中的一件小事，准确地捕捉了小娃娃瞬间的心情，勾画出一幅采莲图。\n莲花盛开的夏日里，天真活泼的儿童，撑着一条小船，偷偷地去池中采摘白莲花玩。兴",
    "background_gwd": "",
    "author_info_gwd": "白居易（772年－846年），字乐天，号香山居士，又号醉吟先生，祖籍太原，到其曾祖父时迁居下邽，生于河南新郑。是唐代伟大的现实主义诗人，唐代三大诗人之一。白居易与元稹共同倡导新乐府运动，世称“元白”，与刘禹锡并称“刘白”。白居易的诗歌题材广泛，形式多样，语言平易通俗，有“诗魔”和“诗王”之称。官至翰林学士、左赞善大夫。公元846年，白居易在洛阳逝世，葬于香山。有《白氏长庆集》传世，代表诗作有《长恨歌》《卖炭翁》《琵琶行》等。"
