    "funTip": "小朋友钓鱼怕吓跑鱼儿，不敢大声说话！",
    "sceneId": "pond",
    "sceneName": "池塘",
    "bgTheme": "pond",
    "theme": "童趣",
    "sentences": [
      {
        "text": "蓬头稚子学垂纶，",
        "py": "péng tóu zhì zi xué chuí lún",
        "charCount": 8,
        "trans": "",
        "words": []
      },
      {
        "text": "侧坐莓苔草映身。",
        "py": "cè zuò méi tái cǎo yìng shēn",
        "charCount": 8,
        "trans": "",
        "words": []
      },
      {
        "text": "路人借问遥招手，",
        "py": "lù rén jiè wèn yáo zhāo shǒu",
        "charCount": 8,
        "trans": "",
        "words": []
      },
      {
        "text": "怕得鱼惊不应人。",
        "py": "pà dé yú jīng bù yīng rén",
        "charCount": 8,
        "trans": "",
        "words": []
      }
    ],
    "translation": "一个头发乱蓬蓬的小孩子，坐在河边草丛里学着钓鱼。他侧着身子坐在青苔上，野草和灌木遮住了他的身影。路人远远地向他问路，他怕吓跑了水里的鱼儿，不敢大声回答，只是摆了摆手，让路人不要出声。",
    "appreciation": "这首诗把一个小孩钓鱼的样子写得活灵活现！'蓬头'说明孩子不修边幅，天真自然；'侧坐莓苔'写出他认真的样子，身体姿势都透着专注。最精彩的是最后两句——路人来问路，孩子明明听到了，但他太担心把鱼吓跑，不敢出声，只好用力招手。这个细节太生动了，我们仿佛看到一个小朋友着急地挥手的样子，又好笑又可爱。诗人观察得这么细，一定是个很爱孩子的人。",
    "background": "胡令能是个很有意思的诗人，他原本是个修锅补碗的工匠，因为喜欢读书写诗，后来成了有名的诗人。他生活在乡村，每天都能看到孩子们玩耍的样子。《小儿垂钓》写的就是他在河边看到的一幕——一个小孩专心钓鱼，路人问路都不敢答，只好拼命摆手。诗人被孩子的认真劲儿逗乐了，就把这个场景写成了诗。",
    "author_info": "胡令能（生卒年不详），唐代诗人，年轻时做过修补器具的工匠，被人们称为'胡钉铰'。他善写生活中的小情趣，风格清新自然。代表作有《小儿垂钓》等。",
    "notes": "蓬头：形容小孩可爱。稚子：年龄小的、懵懂的孩子。垂纶：钓鱼。纶：钓鱼用的丝线。莓：一种野草。苔：苔藓植物。映：遮映。借问：向人打听。鱼惊：鱼儿受到惊吓。应：回应，答应，理睬。",
    "tags": [
      "儿童",
      "垂钓",
      "钓鱼"
    ],
    "gwd_id": "200d28227643",
    "gwd_url": "https://www.guwendao.net/shiwenv_200d28227643.aspx",
    "translation_gwd": "",
    "appreciation_gwd": "《小儿垂钓》是一首以儿童生活为题材的诗作，诗写一“蓬头稚子”学钓鱼，“侧坐莓苔草映身”，路人向小儿招手，想借问打听一些事情，那小儿却“怕得鱼惊不应人”（怕惊了鱼而不置一词），真是活灵活现、惟妙惟肖，形神兼备，意趣盎然。其艺术成就丝毫不亚于杜牧著名的《清明》一诗。\n此诗分垂钓和问路两层，第一、二句重在写垂钓（形），第三、四句重在问路（传神）。\n第一、二句，稚子，小孩也。“蓬头”写其外貌，突出了小孩的幼稚顽皮，天真可爱。“纶”是钓丝，“垂纶”即题目中的“垂钓”，也就是钓鱼。诗人对这垂钓小儿的形貌不加粉饰，直写出山野孩子头发蓬乱的本来面目，使人觉得自",
