    "translation": "春天种下一粒种子，到了秋天就能收获万颗粮食。可是天下到处都没有荒废的田地，辛勤种地的农民还是会因为饥饿而死！",
    "appreciation": "如果说《悯农（锄禾日当午）》是写给每个人看的，那么这首《悯农（春种一粒粟）》就是写给那些当权者看的。前两句说'春种一粒粟，秋收万颗子'，听起来是个美好的数学题——种一得万，多好啊！后两句却陡然一转：四海无闲田，说明农民没有偷懒，地把都种遍了，可还是有农民饿死了。这个转折太震撼了，让人一下子就明白了：问题不在农民不勤劳，而在社会不公。",
    "background": "李绅生活在唐朝后期，当时赋税繁重，农民一年辛苦到头，收获的粮食大部分都要交给官府和地主，自己却常常饿着肚子。李绅看到这种不公平的现象，心里非常愤怒和难过，于是写下这首诗替农民说话。他用最简单直白的对比，揭露了最残酷的社会现实。",
    "author_info": "李绅（772—846），字公垂，唐代诗人、宰相。他早年关心民生疾苦，与白居易、元稹等倡导新乐府运动。他的《悯农》二首是中国最广为人知的古诗之一，被历代儿童诵读。",
    "notes": "悯：怜悯。这里有同情的意思。诗一作《古风二首》。这两首诗的排序各版本有所不同。粟：泛指谷类。秋收：一作“秋成”。子：指粮食颗粒。四海：指全国。闲田：没有耕种的田。犹：仍然。禾：谷类植物的统称。餐：一作“飧”。熟",
