    "funTip": "深秋的枫叶比春天的花还要红呢～",
    "sceneId": "night",
    "sceneName": "月夜",
    "bgTheme": "",
    "theme": "写景",
    "sentences": [
      {
        "text": "远上寒山石径斜，",
        "py": "yuǎn shàng hán shān shí jìng xié",
        "charCount": 8,
        "trans": "",
        "words": []
      },
      {
        "text": "白云生处有人家。",
        "py": "bái yún shēng chù yǒu rén jiā",
        "charCount": 8,
        "trans": "",
        "words": []
      },
      {
        "text": "停车坐爱楓林晚，",
        "py": "tíng chē zuò ài fēng lín wǎn",
        "charCount": 8,
        "trans": "",
        "words": []
      },
      {
        "text": "霜叶红于二月花。",
        "py": "shuāng yè hóng yú èr yuè huā",
        "charCount": 8,
        "trans": "",
        "words": []
      }
    ],
    "translation": "沿着弯弯曲曲的石头小路向山上走去，白云飘浮的地方隐约住着人家。我把车停下来，是因为太喜欢这片枫树林了——那经过秋霜打过的枫叶啊，红艳艳的，比二月的春花还要美丽！",
    "appreciation": "这首诗写出了秋天最美的颜色！诗人坐车上山，看到白云深处有人家，已经觉得很美了。但他突然停下车来，为什么？因为他看到了一片枫林，霜后的枫叶红得像火一样——比春天的花还红！这个比喻太妙了，因为在大家的印象里，春花是最灿烂的，但诗人却说秋天的红叶更胜一筹。这不仅是对秋天的赞美，也是对生命力的赞美：即使在即将凋零的时节，生命依然可以绽放出最绚烂的色彩。",
    "background": "杜牧是晚唐的才子，他喜欢游山玩水，对自然美景有着敏锐的感受力。一个深秋的日子，他乘车走在山间，本来只是赶路，却被一片火红的枫林吸引住了，忍不住停下车来欣赏。深秋在很多诗人笔下是萧条悲伤的，但杜牧却觉得秋天的红叶比春花还美——这和他的性格有关，他是一个乐观开朗的人，善于在别人看不到的地方发现美。",
    "author_info": "杜牧（803—852），字牧之，号樊川居士，晚唐杰出的诗人、散文家。他的诗以七言绝句最为出色，与李商隐并称'小李杜'。代表作有《山行》《清明》《江南春》《泊秦淮》等。",
    "notes": "山行：在山中行走。远上：登上远处的。寒山：深秋季节的山。石径：石子铺成的小路。斜：为倾斜的意思。生：另有版本作“深”。（“生”可理解为在形成白云的地方；“深”可理解为在云雾缭绕的深处）坐：因为。霜叶：枫树的叶子经深秋寒霜之后变成了红色。枫林晚：傍晚时的枫树林。红于：比……更",
    "tags": [
      "小学古诗",
      "幼儿古诗",
      "早教"
    ],
    "gwd_id": "3c36881bd247",
    "gwd_url": "https://www.guwendao.net/shiwenv_3c36881bd247.aspx",
    "translation_gwd": "",
    "appreciation_gwd": "这首诗描绘的是秋之色，展现出一幅动人的山林秋色图。诗里写了山路、人家、白云、红叶，构成一幅和谐统一的画面。这些景物不是并列的处于同等地位，而是有机地联系在一起，有主有从，有的处于画面的中心，有的则处于陪衬地位。简单来说，前三句是宾，第四句是主，前三句是为第四句描绘背景、创造气氛，起铺垫和烘托作用的。\n首句“远上寒山石径斜”，由下而上，写一条石头小路蜿蜒曲折地伸向充满秋意的山峦。“寒”字点明深秋季节;“远”字写出山路的绵长;“斜”字照应句首的“远”字，写出了高而缓的山势。由于坡度不大，故可乘车游山。\n次句“白云深处有人家”，描写诗人山行时所看到的",
    "background_gwd": "",
    "author_info_gwd": ""
