    "gwd_id": "d3e3283daac5",
    "gwd_url": "https://www.guwendao.net/shiwenv_d3e3283daac5.aspx",
    "translation_gwd": "",
    "appreciation_gwd": "这一天正是清明节，诗人杜牧在路上行走，遇上了下雨。清明，虽然是柳绿花红、春光明媚的时节，可也是气候容易发生变化的期间，常常赶上“闹天气”。远在梁代，就有人记载过：在清明前两天的寒食节，往往有“疾风甚雨”。若是正赶在清明这天下雨，还有个专名叫作“泼火雨”。诗人遇上的，正是这样一个日子。\n诗人用“纷纷”两个字来形容那天的“泼火雨”，真是好极了。“纷纷”，若是形容下雪，那该是大雪。但是用来写雨，却是正相反，那种叫人感到“纷纷”的，绝不是大雨，而是细雨。这种细雨，也正就是春雨的特色。细雨纷纷，是那种“天街小雨润如酥”样的雨，它不同于夏天的倾盆暴雨，也和那种淅淅沥沥的秋雨绝",
    "background_gwd": "",
    "author_info_gwd": ""
