    "sentences": [
      {
        "text": "京口瓜洲一水间，",
        "py": "jīng kǒu guā zhōu yī shuǐ jiān",
        "trans": "京口和瓜洲只隔了一条江水，",
        "words": [
          {
            "word": "京口",
            "note": "今江苏镇江"
          },
          {
            "word": "瓜洲",
            "note": "今江苏扬州南"
          }
        ]
      },
      {
        "text": "钟山只隔数重山。",
        "py": "zhōng shān qí gé shù zhòng shān",
        "trans": "钟山也只隔着几座山。",
        "words": [
          {
            "word": "钟山",
            "note": "今南京紫金山"
          }
        ]
      },
      {
        "text": "春风自绿江南岸，",
        "py": "chūn fēng zì lǜ jiāng nán àn",
        "trans": "",
        "words": []
      },
      {
        "text": "明月何时照我还。",
        "py": "míng yuè hé shí zhào wǒ hái",
        "trans": "明月什么时候才能照着我回家呢？",
        "words": []
      }
    ],
    "translation": "京口和瓜洲之间只隔着一道长江，我所居住的钟山也只隔着几座山峰。春风又一次吹绿了长江南岸，明亮的月亮啊，你什么时候能照着我回到家乡呢？",
    "appreciation": "这首诗最妙的地方是一个「绿」字！诗人写春风一吹，整个江南就变绿了，一个「绿」字让看不见的春风有了颜色和生命。诗人站在瓜洲渡口，望着对岸的家乡钟山，虽然只有一江之隔，却因为公务在身无法回去。最后一句「明月何时照我还」，把对家乡的思念寄托给天上的月亮，读来格外动人。",
    "background": "王安石是北宋著名的政治家和文学家。他当宰相时推行变法，这首《泊船瓜洲》就是他在外奔波推行新政时写的。当时他路过瓜洲（今江苏扬州），遥望对岸的京口（今镇江）和自己居住的钟山，想到自己为国家操劳却很久没回家了，心中充满感慨。",
    "author_info": "王安石（1021—1086），字介甫，号半山，北宋政治家、文学家，「唐宋八大家」之一。他曾任宰相，推行著名的「王安石变法」。他的诗风格峭拔有力，尤其擅长写景说理。代表作有《泊船瓜洲》《梅花》《元日》等。",
    "notes": "泊船：停船。泊，停泊。指停泊靠岸。绿：吹绿。京口：古城名。故址在江苏镇江市。瓜洲：镇名，在长江北岸，扬州南郊，即今扬州市南部长江边,京杭运河分支入江处。一水：一条河。古人除将黄河特称为“河”，长江特称为“江”之外，大多数情况下称河流为“水”，如汝水、汉水、浙水、湘水、澧水等等。这里的“一水”指长江。一水间指一水相隔之间。钟山：江",
    "tags": [
      "古诗三百首",
      "中国诗词大会2024",
      "中国诗词大会2023"
    ],
    "gwd_id": "df14e6fd217b",
    "gwd_url": "https://www.guwendao.net/shiwenv_df14e6fd217b.aspx",
    "translation_gwd": "",
    "appreciation_gwd": "这是一首著名的抒情小诗，抒发了诗人眺望江南、思念家乡的深切感情。本诗流露着对故乡的怀念之情，大有急欲飞舟渡江回家和亲人团聚的愿望。\n“京口瓜洲一水间”，诗人站在瓜洲渡口，放眼南望，看到了南边岸上的“京口”与“瓜洲”这么近，中间隔一条江水。“一水间”三字，形容舟行迅疾，顷刻就到。\n“钟山只隔数重山”，以依恋的心情写他对钟山的回望，王安石于景祐四年（1037年）随父王益定居江宁，从此江宁便成了他的息肩之地，第一次罢相后即寓居江宁钟山。“只隔”两字极言钟山之近在咫尺。把“万重山的间隔说得如此平常，反映了诗人对于钟山依恋之深；而事实上，钟山毕竟被“数重山”挡住",
    "background_gwd": "",
    "author_info_gwd": "王安石（1021年12月18日－1086年5月21日），字介甫，号半山，谥文，封荆国公。世人又称王荆公。汉族，北宋抚州临川人（今江西省抚州市临川区邓家巷人），中国北宋著名政治家、思想家、文学家、改革家，唐宋八大家之一。欧阳修称赞王安石：“翰林风月三千首，吏部文章二百年。老去自怜心尚在，后来谁与子争先。”传世文集有《王临川集》、《临川集拾遗》等。其诗文各体兼擅，词虽不多，但亦擅长，且有名作《桂枝香》等。而王荆公最得世人共传之诗句莫过于《泊船瓜洲》中的“春风又绿江南岸，明月何时照我还。”"
