    "funTip": "山河壮丽，可是很多人盼望着回家……",
    "sceneId": "mountain",
    "sceneName": "山林",
    "bgTheme": "mountain",
    "theme": "爱国",
    "sentences": [
      {
        "text": "三万里河东入海，",
        "py": "sān wàn lǐ hé dōng rù hǎi",
        "trans": "三万里的黄河向东流入大海，",
        "words": [
          {
            "word": "三万里",
            "note": "形容黄河很长"
          }
        ]
      },
      {
        "text": "五千仞岳上摩天。",
        "py": "wǔ qiān rèn yuè shàng mó tiān",
        "trans": "五千仞的华山高得快要碰到天了。",
        "words": [
          {
            "word": "仞",
            "note": "古代长度单位"
          },
          {
            "word": "摩",
            "note": "接触，碰到"
          }
        ]
      },
      {
        "text": "遗民泪尽胡尘里，",
        "py": "yí mín lèi jǐn hú chén lǐ",
        "trans": "沦陷区的百姓在异族统治下眼泪都哭干了，",
        "words": [
          {
            "word": "遗民",
            "note": "沦陷区的人民"
          },
          {
            "word": "胡尘",
            "note": "北方少数民族占领区的风沙"
          }
        ]
      },
      {
        "text": "南望王师又一年。",
        "py": "nán wàng wáng shī yòu yī nián",
        "trans": "盼着朝廷军队打回来，又等了一年。",
        "words": [
          {
            "word": "王师",
            "note": "朝廷的军队"
          }
        ]
      }
    ],
    "translation": "三万里长的黄河水向东奔流入大海，五千仞高的华山上接青天。被金人占领的北方百姓，在敌人的统治下眼泪都哭干了。他们向南方盼望朝廷的军队来解救，一年又一年过去了，却始终没有等到。",
    "appreciation": "这首诗的前两句极写山河的壮阔——三万里黄河、五千仞华山，这是多么伟大的祖国！可是后两句笔锋一转，写北方百姓在侵略者的铁蹄下望眼欲穿。山河越壮丽，国土沦丧的痛苦就越深。诗中「泪尽」二字特别沉重，写出百姓等待了一年又一年，眼泪都流干了，朝廷的军队还没来。",
    "background": "陆游退居家乡山阴时，一个初秋的夜晚他睡不着觉，走出屋外凉快，看到满天星斗，想到北方还被金人占领的大好河山和受苦受难的百姓，心中悲愤难平，写下了这首诗。",
    "author_info": "陆游（1125—1210），字务观，号放翁，南宋最伟大的爱国诗人。他一生写了近万首诗，大部分都表达了对国家统一的热切期盼。代表作有《示儿》《游山西村》等。",
    "notes": "将晓：天将要亮。篱门：竹子或树枝编的门。迎凉：出门感到一阵凉风。天汉：银河。搔首：以手搔头。焦急或有所思貌。怆（chuàng）：悲伤。三万里：长度，形容它的长，是虚指。河：指黄河。",
    "tags": [
      "古诗三百首",
      "七言绝句",
      "爱国"
    ],
    "gwd_id": "dab95da71436",
    "gwd_url": "https://www.guwendao.net/shiwenv_dab95da71436.aspx",
    "translation_gwd": "",
    "appreciation_gwd": "第一首落笔写银河西坠，鸡鸣欲曙，渲染出一种苍茫静寂的气氛，表现了有心杀敌无力回天的感慨。第二首写大好河山，陷于敌手，以“望”字为眼，表现了诗人希望、失望而终不绝望的千回百转的心情。诗境雄伟、严肃、苍凉、悲愤。\n组诗的第一首落笔写银河西坠，鸡鸣欲曙，从所见所闻渲染出一种苍茫静寂的气氛。“一再鸣”三字，可见百感已暗集毫端。三四句写“有感”正面。一个“欲”字，一个“怆”字表现了有心杀敌无力回天的感慨。\n要想理解第二首诗，必须理解“五千仞岳”，于此有人说是泰山，因为泰山最高，被列在五岳之首，历代君王也多要去泰山封禅，用黄河与泰山作为中原大好山河的象征似",
    "background_gwd": "这组爱国主义诗篇作于宋光宗绍熙三年（1192年）的秋天，当时陆游已经六十八岁，罢归山阴（今浙江绍兴）故里已经四年。但平静的村居生活并不能使老人的心平静下来。南宋时期，金兵占领了中原地区。诗人作此诗时，中原地区已沦陷于金人之手六十多年了。此时爱国诗人陆游被罢斥归故乡，在山阴乡下向往着中原地区的大好河山，也惦念着中原地区的人民，盼望宋朝能够尽快收复中原，实现统一。此时虽值初秋，暑威仍厉，天气的热闷与心头的煎沸，使他不能安睡。将晓之际，他步出篱门，以舒烦热，心头怅触，写下这两首诗。",
    "author_info_gwd": "陆游（1125年11月13日－1210年1月26日），字务观，号放翁，汉族，越州山阴（今浙江绍兴）人，尚书右丞陆佃之孙，南宋文学家、史学家、爱国诗人。陆游生逢北宋灭亡之际，少年时即深受家庭爱国思想的熏陶。宋高宗时，参加礼部考试，因受秦桧排斥而仕途不畅。孝宗时赐进士出身。中年入蜀，投身军旅生活。嘉泰二年（1202年），宋宁宗诏陆游入京，主持编修孝宗、光宗《两朝实录》和《三朝史》，官至宝章阁待制。晚年退居家乡。创作诗歌今存九千多首，内容极为丰富。著有《剑南诗稿》《渭南文集》《南唐书》《老学庵笔记》等。 陆游一生笔耕不辍，诗词文俱有很高成就，其诗语言平易晓畅、章法整饬谨严，兼具李白的雄奇奔放与杜甫的沉郁悲凉，尤以饱含爱国热情对后世影响深远。"
