    "translation": "梅子变成了金黄色，杏子也长得肥大了；麦花开出了一片雪白，荞麦花却开得稀稀疏疏。夏日天长，篱笆旁没有人经过，只有蜻蜓和蝴蝶在飞来飞去。",
    "appreciation": "这首诗用四种颜色画出了初夏的田园：金黄的梅子、肥大的杏子（黄）、雪白的麦花（白）、稀疏的荞麦花（紫白相间）。前两句是静物特写，后两句是全景——安静的篱笆旁只有蜻蜓和蝴蝶飞舞，整幅画面充满了宁静美好的田园气息。诗人没有抒发感情，但那种对田园生活的喜爱融在每一个景物里。",
    "background": "这是范成大《四时田园杂兴》组诗中的一首，描写的是江南初夏的田园风光。诗人在家乡苏州的石湖边生活，每天观察田园景物的细微变化，把这些美好的瞬间都写进了诗里。",
    "author_info": "范成大（1126—1193），字致能，号石湖居士，南宋著名诗人。他的六十首《四时田园杂兴》是田园诗的经典之作。",
    "notes": "犁锄：农具。犁和锄。流丹：指流血。",
