    "funTip": "夏天西湖的荷花，红得特别耀眼！",
    "sceneId": "pond",
    "sceneName": "池塘",
    "bgTheme": "pond",
    "theme": "送别",
    "sentences": [
      {
        "text": "毕竟西湖六月中，",
        "py": "bì jìng xī hú liù yuè zhōng",
        "charCount": 8,
        "trans": "",
        "words": []
      },
      {
        "text": "风光不与四时同。",
        "py": "fēng guāng bù yǔ sì shí tóng",
        "charCount": 8,
        "trans": "",
        "words": []
      },
      {
        "text": "接天莲叶无穷碧，",
        "py": "jiē tiān lián yè wú qióng bì",
        "charCount": 8,
        "trans": "",
        "words": []
      },
      {
        "text": "映日荷花别样红。",
        "py": "yìng rì hé huā bié yàng hóng",
        "charCount": 8,
        "trans": "",
        "words": []
      }
    ],
    "translation": "到底是六月的西湖呀，风光和别的季节都不一样！接天的莲叶无穷无尽，一片碧绿；映着阳光的荷花，显得格外鲜艳红润。",
    "appreciation": "这首诗写出了西湖六月荷花的极致之美。「接天莲叶无穷碧」——视线所及全都是碧绿的荷叶，一直到天边，太壮观了！「映日荷花别样红」——阳光照在荷花上，那种红色格外耀眼、格外动人。一「碧」一「红」的强烈对比，让画面鲜艳夺目。诗人用一个「别样」二字，把六月西湖的独特之美一下点出来了。",
    "background": "林子方是杨万里的好朋友。有一年六月，林子方要去外地做官，杨万里在西湖边的净慈寺为他送行。清晨时分，杨万里看到西湖上的荷花在朝阳映照下格外美丽，就写了这首诗送给朋友。",
    "author_info": "杨万里（1127—1206），字廷秀，号诚斋，南宋著名诗人。他的诗语言清新活泼，充满生活情趣。代表作有《小池》《晓出净慈寺送林子方》等。",
    "notes": "晓：太阳刚刚升起。净慈寺：全名“净慈报恩光孝禅寺”，与灵隐寺为杭州西湖南北山两大著名佛寺。林子方：作者的朋友，官居直阁秘书。毕竟： 到底。六月中：六月的时候。四时：春夏秋冬四个季节。在这里指六月以外的其他时节。同：相同。接天：像与天空相接。无穷：无边无际。无穷碧：因莲叶面积很广，似与天相接，故呈现无穷",
    "tags": [
      "古诗三百首",
      "幼儿古诗",
      "小学生必背古诗70首"
    ],
    "gwd_id": "3ab4125fd0f1",
    "gwd_url": "https://www.guwendao.net/shiwenv_3ab4125fd0f1.aspx",
    "translation_gwd": "",
    "appreciation_gwd": "这是一首描写西湖六月美丽景色的诗，这首诗是诗中有画，画中有诗的典范作品。\n诗人开篇即说毕竟六月的西湖景色，风光不与其他季节相同，这两句质朴无华的诗句，更加说明夏天的西湖景色的与众不同。这两句是写六月西湖给诗人的总的感受。“毕竟”二字，突出了六月西湖风光的独特、非同一般，给人以丰富美好的想象。首句看似突兀，实际造句大气，虽然读者还不曾从诗中领略到西湖美景，但已能从诗人赞叹的语气中感受到了。诗句似脱口而出，是大惊大喜之余最直观的感受，因而更强化了西湖之美。\n然后，诗人用充满强烈色彩对比的句子，给读者描绘出一幅大红大绿、精彩绝艳的画面：“接天莲叶无穷碧，映日",
    "background_gwd": "",
    "author_info_gwd": "杨万里（1127年10月29日－1206年6月15日），字廷秀，号诚斋。吉州吉水（今江西省吉水县黄桥镇湴塘村）人。南宋著名诗人、大臣，与陆游、尤袤、范成大并称为“中兴四大诗人”。因宋光宗曾为其亲书“诚斋”二字，故学者称其为“诚斋先生”。杨万里一生作诗两万多首，传世作品有四千二百首，被誉为一代诗宗。他创造了语言浅近明白、清新自然，富有幽默情趣的“诚斋体”。杨万里的诗歌大多描写自然景物，且以此见长。他也有不少篇章反映民间疾苦、抒发爱国感情的作品。著有《诚斋集》等。"
