    "funTip": "竹子牢牢扎根岩石中，多大的风都吹不倒！",
    "sceneId": "mountain",
    "sceneName": "山林",
    "bgTheme": "mountain",
    "theme": "咏物",
    "sentences": [
      {
        "text": "咬定青山不放松，",
        "py": "yǎo dìng qīng shān bù fàng sōng",
        "trans": "竹子紧紧咬定青山决不放松，",
        "words": []
      },
      {
        "text": "立根原在破岩中。",
        "py": "lì gēn yuán zài pò yán zhōng",
        "trans": "它的根原本就扎在破裂的岩石中。",
        "words": []
      },
      {
        "text": "千磨万击还坚劲，",
        "py": "qiān mó wàn jī hái jiān jìn",
        "trans": "经过千万次折磨打击还是那样坚韧，",
        "words": [
          {
            "word": "坚劲",
            "note": "坚韧有力"
          }
        ]
      },
      {
        "text": "任尔东西南北风。",
        "py": "rèn ěr dōng xī nán běi fēng",
        "trans": "任凭你刮东西南北风。",
        "words": [
          {
            "word": "任",
            "note": "任凭"
          },
          {
            "word": "尔",
            "note": "你"
          }
        ]
      }
    ],
    "translation": "竹子紧紧咬定青山，绝不放松，它的根深深地扎在破裂的岩石中。经过了千万次的打击，它还是那样坚韧挺拔；不管什么方向的风吹来，它都岿然不动。",
    "appreciation": "「咬定青山不放松」——这个「咬」字太有力了！竹子不是「长」在山上，而是「咬」住青山，写出了竹子顽强不屈的劲头。后面「千磨万击还坚劲，任尔东西南北风」更是一气呵成，表达了面对任何困难和打击都绝不低头的态度。诗人郑板桥一生刚正不阿，这首诗就是他自己品格的写照。",
    "background": "郑板桥是清朝著名的画家、书法家和文学家，「扬州八怪」之一。他做官时因为关心百姓得罪了上司，被罢了官。但他从不后悔自己的选择。这首《竹石》是他题在竹石画上的诗，用竹子的坚韧来表达自己刚直不阿的性格。",
    "author_info": "郑燮（1693—1765），字克柔，号板桥，清代画家、书法家、文学家，「扬州八怪」之一。他以画竹闻名，也写得一手好诗。他做官时清廉爱民，深受百姓爱戴。",
