    "sceneId": "night",
    "sceneName": "月夜",
    "bgTheme": "",
    "theme": "思乡",
    "sentences": [
      {
        "text": "君问归期未有期，",
        "py": "jūn wèn guī qī wèi yǒu qī",
        "charCount": 8,
        "trans": "",
        "words": []
      },
      {
        "text": "巴山夜雨漲秋池。",
        "py": "bā shān yè yǔ zhǎng qiū chí",
        "charCount": 8,
        "trans": "",
        "words": []
      },
      {
        "text": "何当共剪西窗烛，",
        "py": "hé dāng gòng jiǎn xī chuāng zhú",
        "charCount": 8,
        "trans": "",
        "words": []
      },
      {
        "text": "却话巴山夜雨时。",
        "py": "què huà bā shān yè yǔ shí",
        "charCount": 8,
        "trans": "",
        "words": []
      }
    ],
    "translation": "你问我什么时候才能回家，我也不知道啊。巴山的秋夜下起了大雨，池塘里的水都涨满了。什么时候我们才能一起坐在家里的西窗下，剪那根烧过的烛芯，面对面地好好说说这个下雨的夜晚我是多么想你。",
    "appreciation": "这首诗最妙的是时间结构。第一句是'现在'——你问我归期，我说不知道；第二句还是'现在'——雨夜涨水，秋意萧瑟；第三四句跳到'将来'——想象将来团聚时，一起回忆这个雨夜。这种从现在跳到未来的写法，让思念有了温度。李商隐没有直说'我好想回家'，而是描绘了一个温馨的画面：将来我们坐在一起，聊起今天这场雨，聊起我是多么想你。这种'未来回忆现在'的写法，让思念变得尤其深沉。",
    "background": "李商隐在四川（巴蜀）做幕僚的时候，妻子在长安（北方）等他回家。妻子写信问他什么时候回来，他无法确定归期，心里非常难过。一个秋雨绵绵的夜晚，他看着窗外的雨水涨满了池塘，想到远方妻子的牵挂，心中又温暖又酸楚。他铺开纸笔给妻子回信，写下了这首深情的小诗。遗憾的是，他的妻子不久后就去世了，这首诗成了永远的思念。",
    "author_info": "李商隐（约813—约858），字义山，号玉谿生，怀州河内（今河南沁阳）人。晚唐最杰出的诗人之一，与杜牧并称'小李杜'。他的诗深情绵邈，意象独特，尤其以无题诗和爱情诗著称。代表作有《夜雨寄北》《无题》《锦瑟》《登乐游原》等。",
    "notes": "寄北：写诗寄给北方的人。诗人当时在巴蜀（现在四川省），他的亲友在长安，所以说“寄北”。这首诗表达了诗人对亲友的深刻怀念。君：对对方的尊称，等于现代汉语中的“您”。归期：指回家的日期。巴山：指大巴山，在陕西南部和四川东北交界处。这里泛指巴蜀一带。秋池：秋天的池塘。何当：什么时候。共：副词，用在谓语前，表示动作行为是由两个或几",
    "tags": [
      "唐诗三百首",
      "中国诗词大会2024",
      "中国诗词大会2023"
    ],
    "gwd_id": "e46c43d13b97",
    "gwd_url": "https://www.guwendao.net/shiwenv_e46c43d13b97.aspx",
    "translation_gwd": "",
    "appreciation_gwd": "此诗首句“君问归期未有期”，以一问一答开篇，先作停顿再行转折，语调起伏有致，极具表达张力，诗人羁旅在外的愁绪与无法归家的苦闷，已然尽显纸上。紧接着，诗人描绘当下眼前的景致：“巴山夜雨涨秋池”，先前流露的羁旅愁思与归乡不得的苦楚，便与夜雨交织在一起，淅淅沥沥、连绵不绝，涨满秋日池塘，弥漫在巴山的夜色之中。这份愁闷并未直接言说，而是借眼前之景自然流露，诗人更由此拓展开来，放飞想象，另辟全新意境，抒发了“何当共剪西窗烛，却话巴山夜雨时”的心愿。这般构思新奇，出人意料，可设身处地体会，又觉情感真挚恳切，字字皆发自肺腑。\n“何当”这一表期盼的词语，正是从“君问归期未有期”的现实",
    "background_gwd": "这首诗选自《玉溪生诗》卷三，是李商隐留滞巴蜀（今四川省）时寄怀长安亲友之作。因为长安在巴蜀之北，故题作《夜雨寄北》。 在南宋洪迈编的《万首唐人绝句》里，这首诗的题目为《夜雨寄内》，意思是诗是寄给妻子的。他们认为，李商隐于大中五年（851）七月赴东川节度使柳仲郢梓州幕府，而王氏是在这一年的夏秋之交病故，李商隐过了几个月才得知妻子的死讯。现传李诗各本题作《夜雨寄北》，“北”就是北方的人，可以指妻子，也可以指朋友。有人经过考证认为它作于作者的妻子王氏去世之后，因而不是“寄内”诗，而是写赠长安友人的。",
    "author_info_gwd": "李商隐（约813年—约858年），字义山，号玉谿生，又号樊南生，原籍怀州河内（今河南沁阳市）人，后随祖辈移居荥阳（今河南省郑州市），晚唐时期诗人。他擅长诗歌写作，骈文文学价值也很高，是晚唐最出色的诗人之一，和杜牧合称“小李杜”，与温庭筠合称为“温李”，因诗文与同时期的段成式、温庭筠风格相近，且三人都在家族里排行第十六，故并称为“三十六体”。其诗构思新奇，风格秾丽，尤其是一些爱情诗和无题诗写得缠绵悱恻，优美动人，广为传诵。但部分诗歌过于隐晦迷离，难于索解，至有“诗家总爱西昆好，独恨无人作郑笺”之说。因处于牛李党争的夹缝之中，一生很不得志。死后葬于家乡沁阳（今河南焦作市沁阳与博爱县交界之处）。作品收录为《李义山诗集》。"
