    "funTip": "文天祥是民族大英雄，不论遇到什么困难都不屈服！",
    "sceneId": "pond",
    "sceneName": "池塘",
    "bgTheme": "",
    "theme": "爱国",
    "sentences": [
      {
        "text": "辛苦遭逢起一经，",
        "py": "xīn kǔ zāo féng qǐ yī jīng",
        "charCount": 8,
        "trans": "",
        "words": []
      },
      {
        "text": "干戈落落四周星。",
        "py": "gān gē luò luò sì zhōu xīng",
        "charCount": 8,
        "trans": "",
        "words": []
      },
      {
        "text": "山河破碎风拋絮，",
        "py": "shān hé pò suì fēng pāo xù",
        "charCount": 8,
        "trans": "",
        "words": []
      },
      {
        "text": "身世飄摇雨打萍。",
        "py": "shēn shì piāo yáo yǔ dǎ píng",
        "charCount": 8,
        "trans": "",
        "words": []
      },
      {
        "text": "皇恐灘头说皇恐，",
        "py": "huáng kǒng tān tóu shuō huáng kǒng",
        "charCount": 8,
        "trans": "",
        "words": []
      },
      {
        "text": "零丁洋里叹零丁。",
        "py": "líng dīng yáng lǐ tàn líng dīng",
        "charCount": 8,
        "trans": "",
        "words": []
      },
      {
        "text": "人生自古谁无死，",
        "py": "rén shēng zì gǔ shuí wú sǐ",
        "charCount": 8,
        "trans": "",
        "words": []
      },
      {
        "text": "留取丹心照汗青。",
        "py": "liú qǔ dān xīn zhào hàn qīng",
        "charCount": 8,
        "trans": "",
        "words": []
      }
    ],
    "translation": "我因为辛苦读书考中进士出来做官，经历了无数的艰苦战斗，到现在已经四年了。国家危在旦夕，就像狂风中的柳絮一样飘摇。我自己的命运也如雨打的浮萍一样沉浮不定。在惶恐滩头说起当年的战败，心中至今惶恐不安；在零丁洋里感叹自己孤独一人。人生自古以来谁不会死呢？我要留下一颗赤诚的心，永远照耀在历史的天空中！",
    "appreciation": "这首诗最震撼的是最后两句'人生自古谁无死，留取丹心照汗青'——死有什么可怕的？只要死得其所，忠心就会永远留在历史上。这两句诗像是一声惊雷，七百多年来激励了无数中华儿女。文天祥不是不知道只要投降就可以活命，但他选择了死。这首诗的力量在于它不是空洞的口号，而是用生命写成的——诗人写完这首诗后，从容就义。这就是最伟大的诗，是用鲜血和生命写出来的。",
    "background": "文天祥是南宋末年的民族英雄。元朝军队南下，南宋危在旦夕。文天祥组织军队奋勇抵抗，但兵败被俘。元朝将领让他写信劝降其他宋将，他断然拒绝，并写下了《过零丁洋》这首诗表明自己誓死不降的决心。他被押解到大都（今北京）关了三年，元朝皇帝亲自劝降，他依然不肯屈服。最后慷慨就义，年仅四十七岁。",
    "author_info": "文天祥（1236—1283），字履善，号文山，吉州庐陵（今江西吉安）人。南宋末年民族英雄、爱国诗人。二十岁中状元，官至右丞相。抗元兵败被俘后宁死不降，从容就义。他的诗慷慨激昂，充满爱国热忱，《过零丁洋》《正气歌》是千古名篇。",
    "notes": "零丁洋：零丁洋即”伶丁洋“。现在广东省珠江口外。1278年底，文天祥率军在广东五坡岭与元军激战，兵败被俘，囚禁船上曾经过零丁洋。遭逢：遇到朝廷选拔。起一经，因为精通一种经书，通过科举考试而被朝廷起用作官。文天祥",
    "tags": [
      "古诗三百首",
      "初中古诗",
      "七言律诗"
    ],
    "gwd_id": "5796865dca4a",
    "gwd_url": "https://www.guwendao.net/shiwenv_5796865dca4a.aspx",
    "translation_gwd": "",
    "appreciation_gwd": "此诗前二句，诗人回顾平生；中间四句紧承“干戈寥落”，明确表达了作者对当前局势的认识；末二句是作者对自身命运的一种毫不犹豫的选择。全诗表现了慷慨激昂的爱国热情和视死如归的高风亮节，以及舍生取义的人生观，是中华民族传统美德的崇高表现。\n“辛苦遭逢起一经，干戈寥落四周星。”中“起一经”当指天祥二十岁中进士说的，“四周星”即四年。天祥于德祐元年（公元1275，宋恭帝赵㬎的年号），起兵勤王，至祥兴元年（公元1278，南宋卫王赵昺的年号）被俘，恰好四个年头。此自叙生平，思今忆昔。从时间说，拈出“入世”和“勤王”，一说个人出处，一说国家危亡，两件大事。唐宋时期，作为知识分子要想保家",
    "background_gwd": "",
    "author_info_gwd": "文天祥（1236.6.6－1283.1.9），字履善，又字宋瑞，自号文山，浮休道人。汉族，吉州庐陵（今江西吉安县）人，南宋末大臣，文学家，民族英雄。宝祐四年（1256年）进士，官到右丞相兼枢密使。被派往元军的军营中谈判，被扣留。后脱险经高邮嵇庄到泰县塘湾，由南通南归，坚持抗元。祥兴元年（1278年）兵败被张弘范俘虏，在狱中坚持斗争三年多，后在柴市从容就义。著有《过零丁洋》《文山诗集》《指南录》《指南后录》《正气歌》等作品。"
