    "funTip": "",
    "sceneId": "pond",
    "sceneName": "池塘",
    "bgTheme": "",
    "theme": "田园",
    "sentences": [
      {
        "text": "斜阳照墟落，",
        "py": "xié yáng zhào xū luò",
        "charCount": 6,
        "trans": "",
        "words": []
      },
      {
        "text": "穷巷牛羊归。",
        "py": "qióng xiàng niú yáng guī",
        "charCount": 6,
        "trans": "",
        "words": []
      },
      {
        "text": "野老念牧童，",
        "py": "yě lǎo niàn mù tóng",
        "charCount": 6,
        "trans": "",
        "words": []
      },
      {
        "text": "倚杖候荆扉。",
        "py": "yǐ zhàng hòu jīng fēi",
        "charCount": 6,
        "trans": "",
        "words": []
      },
      {
        "text": "雉雊麦苗秀，",
        "py": "zhì gòu mài miáo xiù",
        "charCount": 6,
        "trans": "",
        "words": []
      },
      {
        "text": "蠶眠桑叶稀。",
        "py": "cán mián sāng yè xī",
        "charCount": 6,
        "trans": "",
        "words": []
      },
      {
        "text": "田夫荷鋤至，",
        "py": "tián fū hé chú zhì",
        "charCount": 6,
        "trans": "",
        "words": []
      },
      {
        "text": "相见语依依。",
        "py": "xiāng jiàn yǔ yī yī",
        "charCount": 6,
        "trans": "",
        "words": []
      },
      {
        "text": "即此羨閑逸，",
        "py": "jí cǐ xiàn xián yì",
        "charCount": 6,
        "trans": "",
        "words": []
      },
      {
        "text": "悵然吟式微。",
        "py": "chàng rán yín shì wēi",
        "charCount": 6,
        "trans": "",
        "words": []
      }
    ],
    "translation": "夕阳把余晖洒满了村庄，牛羊沿着小路慢悠悠地回家了。一位老人拄着拐杖站在柴门外，等候放牧归来的孩子。麦田里野鸡在咕咕地叫着，桑叶稀了，蚕宝宝已经吃饱睡了。农夫们扛着锄头回来了，见了面亲热地互相打招呼，说几句家常话。看到这样安宁快乐的生活，我真是羡慕啊！不禁唱起了《式微》这首歌——式微式微，为什么不回家呢？",
    "appreciation": "这首诗好在一个'归'字。牛羊归圈、牧童归来、农夫归家——所有的画面都围绕着'回家'。王维用一系列温暖的生活场景，勾画出田园的安宁与和谐。最动人的是'野老念牧童'，老人倚门等候放牧归来的孩子，那份期盼和慈爱让整个黄昏都暖了起来。王维在官场上奔波多年，看到这样的生活，发出了'式微式微胡不归'的感叹——田园才是他心灵的归宿。",
    "background": "王维中年后在官场和田园之间徘徊。他一方面在朝廷做官，一方面又深深地向往田园生活。一天傍晚，他来到渭河边的一个村庄，看到夕阳下牛羊归圈、农夫收工、老人倚门等候牧童的温馨画面。他被这种安宁和充实深深地打动了，想到自己在官场上勾心斗角的日子，越发觉得这种简单的农家生活才是真正的幸福。于是他写下这首诗，表达了归隐田园的强烈愿望。",
    "author_info": "王维（701—761），字摩诘，号摩诘居士，盛唐诗人、画家，'诗佛'。他深通禅理，诗画兼绝，开创了山水田园诗的新境界。苏轼赞他'味摩诘之诗，诗中有画；观摩诘之画，画中有诗'。代表作有《渭川田家》《山居秋暝》《鹿柴》《竹里馆》等。",
    "notes": "渭川：一作“渭水”。渭水源于甘肃鸟鼠山，经陕西，流入黄河。田家：农家。墟落：村庄。斜阳：一作“斜光”。穷巷：深巷。野老：村野老人。牧童：一作“僮仆”。倚杖：靠着拐杖。荆扉：柴",
    "tags": [
      "唐诗三百首",
      "中国诗词大会2023",
      "山水田园"
    ],
    "gwd_id": "8813f91342c8",
    "gwd_url": "https://www.guwendao.net/shiwenv_8813f91342c8.aspx",
    "translation_gwd": "",
    "appreciation_gwd": "诗人描绘了一幅恬然自乐的田家暮归图，虽都是平常事物，却表现出诗人高超的写景技巧。全诗以朴素的白描手法，写出了人与物皆有所归的景象，映衬出诗人的心情，抒发了诗人渴望有所归，羡慕平静悠闲的田园生活的心情，流露出诗人在官场的孤苦、郁闷。\n“斜阳照墟落，穷巷牛羊归。”墟落：村庄。穷巷：深巷。这两句是说，村庄处处披满夕阳的余晖，牛羊沿着深巷纷纷回归。\n诗人一开头，首先描写夕阳斜照村落的景象，渲染暮色苍茫的浓烈气氛，作为总背景，统摄全篇。接着，诗人一笔就落到“归”字上，描绘了牛羊徐徐归村的情景。诗人痴情的目送牛羊归村，直至沒入深巷。\n“",
    "background_gwd": "",
    "author_info_gwd": "王维（701年－761年，一说699年—761年），字摩诘(jié)，号摩诘居士。汉族，河东蒲州（今山西运城）人，祖籍山西祁县，唐朝诗人，有“诗佛”之称。苏轼评价其：“味摩诘之诗，诗中有画；观摩诘之画，画中有诗。”开元九年（721年）中进士，任太乐丞。天宝年间，拜吏部郎中、给事中。唐肃宗乾元年间任尚书右丞，世称“王右丞”。王维是盛唐诗人的代表，今存诗400余首，重要诗作有《相思》《山居秋暝》等。王维精通佛学，受禅宗影响很大。佛教有一部《维摩诘经》，是王维名和字的由来。王维诗书画都很有名，多才多艺，音乐也很精通。与孟浩然合称“王孟”。"
