    "translation": "风风雨雨送走了春天，漫天飞雪又把春天迎了回来。悬崖上已经结了厚厚的冰，可是还有一朵梅花在那里美丽地开放。梅花不和其他花争春天的宠爱，它只是默默地把春天要来的消息告诉大家。等到满山的花都盛开的时候，梅花就躲在花丛中，开心地微笑着。",
    "appreciation": "毛爷爷笔下的梅花是一个温暖的报信人。别的花都在温暖的春天开放，梅花却在最冷的冬天绽放，告诉人们：春天快来了！最让人感动的是，等春天真的来了，百花盛开，梅花却不抢功劳，在花丛中微笑。这是一种多么无私的精神呀！",
    "background": "1961年是中国困难时期，毛泽东读了陆游的咏梅词后，用同样的词牌写了这首词。与陆游笔下孤傲的梅花不同，毛爷爷笔下的梅花是一个默默奉献的形象，表达了革命者不争功、甘于奉献的精神。",
    "author_info": "毛泽东（1893—1976），新中国的缔造者，也是一位了不起的诗人。他的诗词气势磅礴，充满革命豪情，同时也不乏对自然和人生的细腻感悟。",
    "notes": "冰：形容极度寒冷。丛中笑：百花盛开时，感到欣慰和高兴。犹：还，仍然。俏：俊俏，美好的样子；（此处既能表现梅花的俏丽，又能表现革命者面对困难坚强不屈的美好情操。）烂漫：颜色鲜明而美丽。（文中指花全部盛开的样子）",
    "tags": [
      "幼儿古诗",
      "中国诗词大会2024",
      "中国诗词大会2023"
    ],
    "gwd_id": "e8c610c2308b",
    "gwd_url": "https://www.guwendao.net/shiwenv_e8c610c2308b.aspx",
    "translation_gwd": "",
    "appreciation_gwd": "此词塑造了梅花俊美而坚韧不拔的形象，鼓励人们要有威武不屈的精神和革命到底的乐观主义精神。上阕主要写梅花傲寒开放的美好身姿，描绘梅花的美丽、积极与坚贞；下阕主要写梅花的精神风貌，表现了梅花坚强不屈、不畏寒冷，对春天充满信心和谦虚的风格。\n上阕主要写梅花傲寒开放的俏丽身姿。起始二句叙季节的变换，既平直自然，又蕴含哲理。第一句才说“春归”，第二句就说“春到”。春归是梅花在风雨中所送，春到是梅花在飞雪中所迎。很显然，这里的“迎春”、“送春”者，不是“风雨”、“飞雪”，而是梅和梅花。在风雨中送走春天时，梅花虽已凋谢但在飞雪中迎来春天时，梅花却正吐艳。这两句对仗工整，拟人形象，生",
    "background_gwd": "1960年6月，在罗马尼亚首都布加勒斯特召开共产党和工人党代表会议，苏共代表团和中共代表团发生激烈争论。会后，苏联撤走在华的全部专家，撕毁几百个协定和合同，停止供应重要设备。当时，以美国为首的西方国家一直对华经济封锁。苏联的严重措施，实际上断绝了中国从国外获取先进技术装备的正常渠道。与此同时，中国正处在三年困难时期，正经历着前所未有的严峻考验。在严重困难面前，毛泽东始终保持着中华民族大无畏的气概顶住了大国沙文主义的压力。中国人民独立自主、自力更生的精神，赢得了普遍的赞誉。\n1961年12月，毛泽东在广州，为即将召开的中共中央扩大的工作会议做准备。他读了陆游的《卜算子·",
    "author_info_gwd": ""
