    "sentences": [
      {
        "text": "七夕今宵看碧霄，",
        "py": "qī xī jīn xiāo kàn bì xiāo",
        "charCount": 8,
        "trans": "",
        "words": []
      },
      {
        "text": "牵牛织女渡河桥。",
        "py": "qiān niú zhī nǚ dù hé qiáo",
        "charCount": 8,
        "trans": "",
        "words": []
      },
      {
        "text": "家家乞巧望秋月，",
        "py": "jiā jiā qǐ qiǎo wàng qiū yuè",
        "charCount": 8,
        "trans": "",
        "words": []
      },
      {
        "text": "穿尽红丝几万条。",
        "py": "chuān jǐn hóng sī jǐ wàn tiáo",
        "charCount": 8,
        "trans": "",
        "words": []
      }
    ],
    "translation": "七月初七的晚上，人们抬头看着天上的牵牛星和织女星。家家户户的女孩子都穿针引线，希望织女姐姐能赐给自己一双巧手。她们对着月亮，用细细的红丝线穿过有九个孔的小针，一穿就是好多根。天上的星星眨着眼睛，地上的女孩们许着心愿，这个夜晚充满了美好的期盼。",
    "appreciation": "这首诗描写了七夕节最有趣的习俗——乞巧。古时候，女孩子在七夕夜比赛穿针，看谁的手最巧，还向织女许愿。诗中「家家乞巧望秋月，穿尽红丝几万条」，写得热闹又美丽，让小朋友仿佛看到了满院子穿针引线的姑娘们。",
    "background": "七月初七是七夕节，传说这天牛郎织女在鹊桥相会。织女是有名的巧手仙女，所以古代女孩子在这一天向她「乞巧」——祈求心灵手巧。林杰小时候特别聪明，六岁就会写诗，这首诗就是他的名作。",
    "author_info": "林杰（约831—847），唐代神童诗人。他六岁就能作诗，精通书法和音乐，可惜十七岁就去世了。他留下的诗很少，《乞巧》是他最广为人知的一首。",
    "notes": "乞巧节：古代节日，在农历七月初七日，又名七夕。旧时风俗，妇女们于这一天牛郎织女相会之夜穿针，向织女学巧，谓乞巧。碧霄：指浩瀚无际的青天。几万条：比喻多。",
    "tags": [
      "小学古诗",
      "幼儿古诗",
      "中国诗词大会2023"
    ],
    "gwd_id": "e152d043be94",
    "gwd_url": "https://www.guwendao.net/shiwenv_e152d043be94.aspx",
    "translation_gwd": "",
    "appreciation_gwd": "农历七月初七夜晚，俗称“七夕”，又称“女儿节”、“少女节”，是传说中隔着“天河”的牛郎和织女在鹊桥上相会的日子。古代，七夕的民间活动主要是乞巧。所谓乞巧，就是向织女乞求一双巧手的意思。乞巧最普遍的方式是对月穿针，如果线从针孔穿过，就叫得巧。这一习俗唐宋最盛。\n《乞巧》是唐代诗人林杰描写民间七夕乞巧盛况的名诗，是一首想象丰富、流传很广的古诗。诗句浅显易懂，涉及到家喻户晓的神话传说故事，表达了少女们乞取智巧、追求幸福的美好心愿。\n“七夕今宵看碧霄，牵牛织女渡河桥。”“碧霄”指浩瀚无际的青天。开头两句叙述的就是牛郎织女的民间故事。一年一度的七夕又来到了，家家",
    "background_gwd": "",
    "author_info_gwd": "林杰(831—847)字智周，福建人，唐代诗人。小时候非常聪明，六岁就能赋诗，下笔即成章。又精书法棋艺。卒，年仅十七。《全唐诗》存其诗两首。《乞巧》是唐代诗人林杰描写民间七夕乞巧盛况的名诗。农历七月初七夜晚，俗称“七夕”，又称“女儿节”“少女节”。是传说中隔着“天河”的牛郎和织女在鹊桥上相会的日子。过去，七夕的民间活动主要是乞巧，所谓乞巧，就是向织女乞求一双巧手的意思。乞巧最普遍的方式是对月穿针，如果线从针孔穿过，就叫得巧。这一习俗唐宋最盛。"
