    "translation": "走过一座山又一座山，渡过一条河又一条河，一直走到夜深了，帐篷里点起千万盏灯。风一更又一更地吹，雪一更又一更地下，吵得人怎么也睡不着。在远离家乡的地方，连风声雪声都让人觉得格外孤单。故乡没有这样吵闹的风雪吧？那里的夜晚一定是安安静静的。",
    "appreciation": "纳兰性德用最简单的话写出了最深的思念。「山一程，水一程」像走路数步子的感觉，一步接一步离家越来越远。「聒碎乡心梦不成」——风雪太吵了，连梦都做不成——这句特别让人心疼。小朋友如果想家了，是不是也像这样，什么都觉得不对劲呢？",
    "background": "纳兰性德是康熙皇帝的侍卫，经常跟随皇帝出行。这一年他跟随皇帝出关东巡，塞外的风雪之夜，远离家乡的他倍感孤独，在帐篷里写下了这首《长相思》。",
    "author_info": "纳兰性德（1655—1685），清代著名词人。他出身贵族，才华横溢，词写得特别真挚感人。人们称赞他是「清代第一词人」，可惜英年早逝，只活了三十岁。",
    "notes": "程：道路、路程，山一程、水一程，即山长水远。榆关：即今山海关，在今河北秦皇岛东北。那畔：即山海关的另一边，指身处关外。帐：军营的帐篷，千帐言军营之多。更：旧时一夜分五更，每更大约两小时。风一更、雪一更，即言整夜风雪交加也。聒（guō）：声音嘈杂，这里指风雪声。故园：故乡，这里指北",
    "tags": [
      "小学古诗",
      "幼儿古诗",
      "抒情"
    ],
