    "funTip": "沙漠的沙子亮得像雪，弯月像银钩挂在天空～",
    "sceneId": "mountain",
    "sceneName": "山林",
    "bgTheme": "mountain",
    "theme": "咏物",
    "sentences": [
      {
        "text": "大漠沙如雪，",
        "py": "dà mò shā rú xuě",
        "charCount": 6,
        "trans": "",
        "words": []
      },
      {
        "text": "燕山月似钩。",
        "py": "yàn shān yuè shì gōu",
        "charCount": 6,
        "trans": "",
        "words": []
      },
      {
        "text": "何当金络脑，",
        "py": "hé dāng jīn luò nǎo",
        "charCount": 6,
        "trans": "",
        "words": []
      },
      {
        "text": "快走踏清秋。",
        "py": "kuài zǒu tà qīng qiū",
        "charCount": 6,
        "trans": "",
        "words": []
      }
    ],
    "translation": "辽阔的大沙漠，沙子像白雪一样洁白；燕山上的月亮弯弯的，像一把银钩。什么时候才能给马儿戴上金色的笼头呢？让它在大好秋天里，自由自在地奔驰在战场上！这匹骏马已经准备好了，它的主人也跃跃欲试，只等一个机会，就能大显身手啦！",
    "appreciation": "李贺写了二十三首马诗，这是最有名的一首。表面上在写一匹渴望驰骋的好马，实际上在写自己——一个有才华的人希望被重用。「快走踏清秋」五个字，好像能看到骏马奔腾的样子，充满了力量和速度感，让小朋友读起来热血沸腾！",
    "background": "李贺才华横溢，但因为父亲名字的原因不能考进士，一生郁郁不得志。他写《马诗》二十三首，借马来表达自己渴望被赏识、为国效力的心情。这首诗中的骏马就是诗人自己的写照。",
    "author_info": "李贺（790—816），人称「诗鬼」，中唐著名诗人。他想象力惊人，诗风瑰丽奇特，有很多神仙鬼怪的内容。可惜身体不好，二十七岁就去世了，但他留下的诗篇非常珍贵。",
    "notes": "",
