    "translation": "树林里暗暗的，一阵风吹过，草丛沙沙作响，好像有什么东西藏在里面。将军以为是老虎来了，立刻拉起弓放了一箭！天亮了，大家去找昨晚射出的那支箭，你猜怎么着？箭深深地插在一块大石头里面！将军的力气好大呀，连石头都能射穿，真是太厉害了！",
    "appreciation": "这首小诗像一个精彩的微型电影！「林暗草惊风」先制造紧张气氛，将军拉弓射箭的动作利落帅气。最好玩的是第二天找箭——箭竟然插在石头里！这是真的吗？传说汉朝的飞将军李广就曾把箭射进石头，卢纶用这个典故，让诗里的将军也神勇无比。",
    "background": "《塞下曲》是卢纶写的一组边塞诗。这首诗借用了汉朝名将李广的故事：传说李广打猎时误把石头当老虎，一箭射去，箭头竟然没入石中。卢纶用这个故事来赞美守边将军的勇武。",
    "author_info": "卢纶（约748—约799），唐代诗人，「大历十才子」之一。他写的边塞诗特别有气势，读起来让人热血沸腾。《塞下曲》组诗是他最著名的作品。",
    "notes": "塞下曲：古时边塞的一种军歌。月黑：没有月光。单于（chán yú ）：匈奴的首领。这里指入侵者的最高统帅。遁：逃走。将：带领。轻骑：轻装快速的骑兵。逐：追赶。满：沾满。",
