    "gwd_id": "9a9463173105",
    "gwd_url": "https://www.guwendao.net/shiwenv_9a9463173105.aspx",
    "translation_gwd": "",
    "appreciation_gwd": "《塞下曲》为汉乐府旧题，属《横吹曲辞》，内容多写边塞征战。原共六首，蘅塘退士选其四首。这是卢纶组诗《塞下曲》中的第三首。卢纶曾任幕府中的元帅判官，对行伍生活有体验，描写此类生活的诗比较充实，风格雄劲。这首诗写将军雪夜准备率兵追敌的壮举，气概豪迈。\n诗由写景开始，“月黑雁飞高”并非眼中之景，而是意中之景。雪夜月黑，本不是雁飞的正常时刻；而宿雁惊飞，透露出敌人正在行动。寥寥五字，既交代了时间为冬季，又烘托出了战前的紧张气氛。\n“单于夜遁逃”，敌人夜间行动，并非率兵来袭，而是借月色的掩护仓皇逃遁。诗句语气肯定，判断明确，充满了对敌人的蔑视和我军的必胜信念，令",
    "background_gwd": "卢纶早年多次应举不第，后经元载、王缙等举荐才谋的官职。朱泚之乱过后，咸宁王浑瑊出镇河中，提拔卢纶为元帅府判官。这是卢纶边塞生活的开始。在军营中，卢纶看到的都是雄浑肃穆的边塞景象，接触到的都是粗犷豪迈的将士，在这种背景下创作了《和张仆射塞下曲六首》这组诗，本诗是组诗中的第三首。",
    "author_info_gwd": "卢纶（739年—799年），字允言，河中蒲州（今山西永济县）人。唐代诗人，大历十才子之一。唐玄宗天宝末年举进士，遇乱不第；唐代宗朝又应举， 屡试不第。大历六年，经宰相元载举荐，授阌乡尉；后由宰相王缙荐为集贤学士，秘书省校书郎，升监察御史。出为陕州户曹、河南密县令。之后元载、王缙获罪，遭到牵连。唐德宗朝，复为昭应县令，出任河中元帅浑瑊府判官，官至检校户部郎中。不久去世。著有《卢户部诗集》。"
